using System.Text.Json.Nodes;
using NexoLoL.Core;

if(args.Contains("--native-timers-live")){using var api=LeagueClient.Open();await NativeTimerSettings.ConfigureAsync(api,true);Console.WriteLine("LIVE: cronômetros avançados ativados e confirmados pelo LoL.");return 0;}
int passed=0,failed=0;
async Task Test(string name,Func<Task> body){try{await body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
void True(bool condition){if(!condition)throw new Exception("comportamento esperado não observado");}
string temp=Path.Combine(Path.GetTempPath(),"nexo-import-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
var q=new BuildQuery(26,"zilean",GameMode.Rift,"support",Patch:"16.23");
var doc=new BuildDocument(q,"16.23","LoLalytics",BuildParsers.Url(q),DateTimeOffset.UtcNow,[new("Mais jogada",[new(3865),new(2003,2)],[new(2065),new(3158)],[new(2524)],"QEW","",new(8200,8100,[8214,8226,8210,8232,8105,8126,5007,5008,5001]))]);
ClientImporter Importer()=>new(Path.Combine(temp,Guid.NewGuid().ToString("N")));
await Test("fora da seleção não altera itens nem runas",async()=>{using var api=new FakeApi{Phase="Lobby"};await Importer().ApplyAsync(api,doc,0,new());True(api.Writes.Count==0);});
await Test("importa itens preservando conjuntos pessoais e de outros apps",async()=>{using var api=new FakeApi();var result=await Importer().ApplyAsync(api,doc,0,new(Runes:false));True(result.Success);True(api.Sets["itemSets"]!.AsArray().Count==3);True(api.Sets["itemSets"]![0]!["title"]!.ToString()=="Meu conjunto");True(api.Sets["itemSets"]![1]!["uid"]!.ToString()=="blitz-keep");True(api.Sets["itemSets"]!.AsArray().Last()!["blocks"]![0]!["items"]![1]!["count"]!.GetValue<int>()==2);});
await Test("cria e ativa runas usando IDs do catálogo",async()=>{using var api=new FakeApi();var result=await Importer().ApplyAsync(api,doc,0,new(Items:false));True(result.Success);True(api.Pages.Count==2);var page=api.Pages.Last()!;True(page["primaryStyleId"]!.GetValue<int>()==8200);True(page["subStyleId"]!.GetValue<int>()==8100);True(page["selectedPerkIds"]!.AsArray().Count==9);True(api.CurrentId==page["id"]!.GetValue<int>());});
await Test("sem vaga reutiliza só página ativa com backup restaurável",async()=>{using var api=new FakeApi{CanAdd=false};var original=api.Pages[0]!.DeepClone();var importer=Importer();var result=await importer.ApplyAsync(api,doc,0,new(Items:false));True(result.Success);True(api.Pages.Count==1);True(api.Writes.All(w=>w.Method!=HttpMethod.Delete));await importer.RestoreRunesAsync(api);True(api.Pages[0]!["name"]!.ToString()==original["name"]!.ToString());True(api.Pages[0]!["selectedPerkIds"]!.ToJsonString()==original["selectedPerkIds"]!.ToJsonString());});
await Test("página ativa não editável não é apagada",async()=>{using var api=new FakeApi{CanAdd=false};api.Pages[0]!["isEditable"]=false;var r=await Importer().ApplyAsync(api,doc,0,new(Items:false));True(!r.Success);True(api.Writes.Count==0);});
await Test("opção de não reutilizar página respeita limite de vagas",async()=>{using var api=new FakeApi{CanAdd=false};var r=await Importer().ApplyAsync(api,doc,0,new(Items:false,ReuseActivePage:false));True(!r.Success);True(api.Writes.Count==0);});
await Test("Desordem importa itens e não toca nas runas",async()=>{using var api=new FakeApi{Mode="KIWI",Queue=2400};var d=doc with{Query=q with{Mode=GameMode.Mayhem,Role="default"},Variants=[doc.Variants[0] with{Runes=null}]};var r=await Importer().ApplyAsync(api,d,0,new());True(r.Success);True(api.Writes.All(w=>!w.Path.Contains("perks")));});
await Test("consulta manual de outro campeão não é aplicada à seleção",async()=>{using var api=new FakeApi{Champion=103};var r=await Importer().ApplyAsync(api,doc,0,new());True(!r.Success);True(api.Writes.Count==0);});
await Test("troca de campeão antes da escrita cancela importação antiga",async()=>{using var api=new FakeApi();api.OnRead=path=>{if(path.Contains("item-sets/"))api.Champion=103;};var r=await Importer().ApplyAsync(api,doc,0,new(Runes:false));True(!r.Success);True(api.Writes.Count==0);});
await Test("troca da conta antes da escrita cancela importação antiga",async()=>{using var api=new FakeApi();api.OnRead=path=>{if(path.Contains("item-sets/"))api.Owner="other";};var r=await Importer().ApplyAsync(api,doc,0,new(Runes:false));True(!r.Success);True(api.Writes.Count==0);});
await Test("não repete importação no mesmo contexto de seleção",async()=>{using var api=new FakeApi();var i=Importer();await i.ApplyAsync(api,doc,0,new());int writes=api.Writes.Count;await i.ApplyAsync(api,doc,0,new());True(api.Writes.Count==writes);});
await Test("reutiliza conjunto e página Nexo em vez de duplicar",async()=>{using var api=new FakeApi();var i=Importer();await i.ApplyAsync(api,doc,0,new());int setCount=api.Sets["itemSets"]!.AsArray().Count,pageCount=api.Pages.Count;await i.ApplyAsync(api,doc,0,new(),true);True(api.Sets["itemSets"]!.AsArray().Count==setCount);True(api.Pages.Count==pageCount);});
await Test("falha de leitura posterior não informa sucesso",async()=>{using var api=new FakeApi{IgnoreWrites=true};var r=await Importer().ApplyAsync(api,doc,0,new(Runes:false));True(!r.Success);});
await Test("cancelamento do usuário não escreve no cliente",async()=>{using var api=new FakeApi();using var c=new CancellationTokenSource();c.Cancel();try{await Importer().ApplyAsync(api,doc,0,new(),ct:c.Token);}catch(OperationCanceledException){}True(api.Writes.Count==0);});
await Test("troca A para B e volta A reaplica runas corretas",async()=>{using var api=new FakeApi();var i=Importer();await i.ApplyAsync(api,doc,0,new());api.Champion=103;var other=doc with{Query=q with{ChampionId=103,Slug="ahri"},Variants=[doc.Variants[0] with{Runes=new(8400,8200,[8465,8463,8473,8242,8226,8210,5007,5008,5001])}]};await i.ApplyAsync(api,other,0,new());api.Champion=26;await i.ApplyAsync(api,doc,0,new());var active=await api.GetAsync("/lol-perks/v1/currentpage");True(active!["primaryStyleId"]!.GetValue<int>()==8200);});
await Test("preserva conjunto adicionado durante a revalidação",async()=>{using var api=new FakeApi();bool read=false,added=false;api.OnRead=p=>{if(p.Contains("item-sets/"))read=true;if(p.Contains("current-summoner")&&read&&!added){api.Sets["itemSets"]!.AsArray().Add(new JsonObject{["uid"]="new-personal",["title"]="Novo conjunto"});added=true;}};await Importer().ApplyAsync(api,doc,0,new(Runes:false));True(api.Sets["itemSets"]!.AsArray().Any(s=>s?["uid"]?.ToString()=="new-personal"));});
await Test("restauração interrompe se a partida começar entre escritas",async()=>{using var api=new FakeApi{CanAdd=false};var i=Importer();await i.ApplyAsync(api,doc,0,new(Items:false));int before=api.Writes.Count(w=>w.Path=="/lol-perks/v1/currentpage");api.OnWrite=(m,p,b)=>{if(p.StartsWith("/lol-perks/v1/pages/"))api.Phase="InProgress";};try{await i.RestoreRunesAsync(api);}catch(InvalidDataException){}True(api.Writes.Count(w=>w.Path=="/lol-perks/v1/currentpage")==before);});
await Test("restauração incompleta conserva backup para nova tentativa",async()=>{using var api=new FakeApi{CanAdd=false};var i=Importer();await i.ApplyAsync(api,doc,0,new(Items:false));api.IgnoreRuneName=true;bool rejected=false;try{await i.RestoreRunesAsync(api);}catch(InvalidDataException){rejected=true;}True(rejected);api.IgnoreRuneName=false;await i.RestoreRunesAsync(api);True(api.Pages[0]!["name"]!.ToString()=="Minha página");});
await Test("A depois de falha parcial em B não usa confirmação antiga",async()=>{using var api=new FakeApi();var i=Importer();await i.ApplyAsync(api,doc,0,new(Items:false));api.Champion=103;var other=doc with{Query=q with{ChampionId=103,Slug="ahri"},Variants=[doc.Variants[0] with{Runes=new(8400,8200,[8465,8463,8473,8242,8226,8210,5007,5008,5001])}]};api.OnWrite=(m,p,b)=>{if(p=="/lol-perks/v1/currentpage")throw new HttpRequestException("falha depois de aplicar");};True(!(await i.ApplyAsync(api,other,0,new(Items:false))).Success);api.OnWrite=null;api.Champion=26;await i.ApplyAsync(api,doc,0,new(Items:false));var active=await api.GetAsync("/lol-perks/v1/currentpage");True(active!["primaryStyleId"]!.GetValue<int>()==8200);});
await SpellTests.Run(Test,doc,Importer);
await TimerTests.Run(Test);

Directory.Delete(temp,true);Console.WriteLine($"{passed} passed, {failed} failed");return failed>0?1:0;
